 "content": "from collections import deque


def transform(grid):
    """Return a 3x3 solid block in the color of the largest non-background region."""
    h, w = len(grid), len(grid[0])
    seen = set()
    largest_size = 0
    largest_color = None
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if size > largest_size:
                largest_size, largest_color = size, color
    return [[largest_color] * 3 for _ in range(3)]
